tasks_bp = Blueprint('tasks', __name__, url_prefix='/tasks')

@tasks_bp.route('', methods=['GET'])
@token_required
def get_tasks(current_user):
    page = request.args.get('page', 1, type=int)
    per_page = request.args.get('per_page', 10, type=int)
    status = request.args.get('status')
    category_id = request.args.get('category_id', type=int)
    priority_id = request.args.get('priority_id', type=int)
    assigned_to = request.args.get('assigned_to', type=int)
    search = request.args.get('search')

    if per_page > 100:
        per_page = 100

    query = Task.query.filter_by(created_by=current_user.id)

    if status:
        try:
            status_enum = TaskStatus[status.upper()]
            query = query.filter_by(status=status_enum)
        except KeyError:
            return jsonify({'error': 'Invalid status'}), 400

    if category_id:
        category = Category.query.filter_by(id=category_id, user_id=current_user.id).first()
        if not category:
            return jsonify({'error': 'Category not found'}), 404
        query = query.filter_by(category_id=category_id)

    if priority_id:
        priority = Priority.query.get(priority_id)
        if not priority:
            return jsonify({'error': 'Priority not found'}), 404
        query = query.filter_by(priority_id=priority_id)

    if assigned_to:
        query = query.filter_by(assigned_to=assigned_to)

    if search:
        query = query.filter(
            or_(
                Task.title.ilike(f'%{search}%'),
                Task.description.ilike(f'%{search}%')
            )
        )

    pagination = query.order_by(Task.created_at.desc()).paginate(
        page=page,
        per_page=per_page,
        error_out=False
    )

    return jsonify({
        'tasks': [task.to_dict() for task in pagination.items],
        'pagination': {
            'page': page,
            'per_page': per_page,
            'total': pagination.total,
            'pages': pagination.pages
        }
    }), 200

